UPDATE articles SET body = body || E'\n\n## Частые вопросы\n\n### Сколько показателей входит в биохимический анализ крови?\n\nБиохимия включает более 20 показателей, но чаще врач назначает несколько нужных, например холестерин или глюкозу.\n\n### Как подготовиться к биохимическому анализу крови?\n\nКровь берут из вены натощак после 12–14 часов голода, в первой половине дня, с 8 до 11 часов. За сутки исключите алкоголь, а за 1–2 часа до анализа не курите и избегайте нагрузок.\n\n### Почему нормы в разных лабораториях отличаются?\n\nЛаборатории используют разные методы и оборудование, поэтому референсы одного и того же показателя могут отличаться. Ориентируйтесь на значения, напечатанные в вашем бланке.\n\n### Что значит один показатель вне нормы?\n\nНорма охватывает центральные 95 процентов результатов здоровых людей, поэтому пять процентов здоровых по определению оказываются за её пределами. Единичное отклонение не всегда повод для тревоги, его оценивает врач.' WHERE slug = 'biohimicheskij-analiz-krovi-istoriya-normy-rasshifrovka';